import {
    Table,
    BooleanColumn,
    StringColumn,
    ReferenceColumn,
    BasicImageColumn,
    TranslatedTextColumn,
    OverrideColumn,
} from '../../db'

export const sys_scope = Table({
    allowWebServiceAccess: true,
    attributes: {
        metadata_link_exempt: true,
    },
    audit: true,
    extends: 'sys_package',
    extensible: true,
    label: 'Application',
    name: 'sys_scope',
    schema: {
        private: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Private apps cannot be configured when installed',
                    label: 'Private',
                    plural: 'Privates',
                },
            ],
        }),
        vendor: StringColumn({
            label: [
                {
                    hint: 'Identifies which organization owns the application',
                    label: 'Vendor',
                    plural: 'Vendors',
                },
            ],
        }),
        scoped_administration: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'When checked, System Administrators will be prevented from accessing the application',
                    label: 'Application administration',
                    plural: 'Application administrations',
                },
            ],
        }),
        restrict_table_access: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'Restrict design time access to tables outside application scope',
                    label: 'Restrict Table Choices',
                    plural: 'Restrict Table Choices',
                },
            ],
        }),
        application_runtime_policy: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            default: 'none',
            choices: {
                none: {
                    label: 'None',
                    sequence: 1,
                },
                tracking: {
                    label: 'Tracking',
                    sequence: 2,
                },
                enforcing: {
                    label: 'Enforcing',
                    sequence: 3,
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'Application Runtime Policy',
        }),
        license: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            label: 'Subscription',
            referenceTable: 'license_details',
            referenceFloats: true,
            referenceQual:
                "javascript:((!SNC.UsageAnalyticsScriptUtils.canRouteToEMS()) ? SNC.UsageAnalyticsScriptUtils.getSubscriptionsForMappingQuery() : 'sys_idISEMPTY');",
        }),
        guided_setup_guid: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: [
                {
                    hint: 'The Guided Setup to start when the application is installed/upgraded.',
                    label: 'Guided Setup',
                    plural: 'Guided Setups',
                },
            ],
            referenceTable: 'gsw_content',
        }),
        logo: BasicImageColumn({}),
        js_level: StringColumn({
            default: 'es_latest',
            choices: {
                traditional: {
                    label: 'Compatibility Mode',
                    sequence: 1,
                    hint: 'ECMAScript3 with ServiceNow behaviors and extensions',
                },
                helsinki_es5: {
                    label: 'ES5 Standards Mode',
                    sequence: 2,
                    hint: 'ECMAScript5 with extensions',
                },
                es_latest: {
                    label: 'ECMAScript 2021 (ES12)',
                    sequence: 3,
                    hint: "ServiceNow's implementation of ECMAScript 2021 (aka, ES12 and ES2021). Please refer to Release documentation for compatibility.",
                },
            },
            dropdown: 'dropdown_without_none',
            label: 'JavaScript Mode',
        }),
        short_description: TranslatedTextColumn({
            attributes: {
                ts_weight: '50',
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: [
                {
                    hint: 'Short description of application',
                    label: 'Short description',
                    plural: 'Short descriptions',
                },
            ],
            maxLength: 500,
        }),
        scope: StringColumn({
            attributes: {
                ts_weight: '50',
            },
            label: [
                {
                    hint: 'Identifies the unique application scope (x_[companyCode]_[shortAppId])',
                    label: 'Scope',
                    plural: 'Scopes',
                },
            ],
            maxLength: 18,
        }),
        template: StringColumn({
            choices: {
                esa: {
                    label: 'ESA',
                    sequence: 1,
                },
                service: {
                    label: 'Service',
                    sequence: 10,
                },
            },
            dropdown: 'dropdown_with_none',
            label: 'Template',
            readOnly: true,
            readOnlyOption: 'strict_read_only',
        }),
        vendor_prefix: StringColumn({
            label: [
                {
                    hint: 'Identifies the unique short form organization code',
                    label: 'Vendor prefix',
                    plural: 'Vendor prefixes',
                },
            ],
            readOnly: true,
            readOnlyOption: 'strict_read_only',
        }),

        can_edit_in_studio: BooleanColumn({
            default: true,
            label: [
                {
                    hint: 'Allows a user to edit application files in studio',
                    label: 'Can Edit Application in Studio',
                    plural: 'Can Edit Application in Studios',
                },
            ],
        }),
        runtime_access_tracking: StringColumn({
            attributes: {
                edge_encryption_enabled: true,
            },
            choices: {
                permissive: {
                    label: 'Tracking',
                    sequence: 2,
                },
                enforcing: {
                    label: 'Enforcing',
                    sequence: 3,
                },
            },
            dropdown: 'dropdown_with_none',
            label: [
                {
                    hint: 'Script interaction with other applications is controlled by the runtime access system. Tracking logs access requests and allows scripts to execute. Enforcing logs access requests but requires administrator authorization before script execution proceeds.',
                    label: 'Runtime Access Tracking',
                    plural: 'Runtime Access Trackings',
                },
            ],
        }),
        sn_managed: BooleanColumn({
            default: false,
            label: [
                {
                    hint: 'True if the application is managed by ServiceNow',
                    label: 'ServiceNow Managed',
                    plural: 'ServiceNow Managed',
                },
            ],
        }),
        subscription_entitlement: ReferenceColumn({
            attributes: {
                encode_utf8: false,
                readonly_clickthrough: true,
            },
            label: 'Subscription',
            referenceTable: 'subscription_entitlement',
            referenceFloats: true,
            referenceQual:
                'javascript: new sn_entitlement.EligibleLicenseQueryBuilder().getEligibleCustomAppSubscriptionsQuery();',
        }),
        '': OverrideColumn({
            baseTable: '',
            default: 'javascript:gs.getAppCreatorCompanyCode()',
        }),
    },
    textIndex: true,
})
